let context = { balance: 100 };

async function toolCallA() {
  const current = context.balance; // reads 100
  await new Promise((r) => setTimeout(r, 10));
  context.balance = current + 50; // writes 150
}

async function toolCallB() {
  const current = context.balance; // also reads 100
  await new Promise((r) => setTimeout(r, 5));
  context.balance = current + 30; // writes 130, overwriting A's update
}

await Promise.all([toolCallA(), toolCallB()]);
console.log(context.balance); // 130, the plus fifty update vanished

let context = { balance: 100, version: 1 };

function applyUpdate(expectedVersion, delta) {
  if (context.version !== expectedVersion) {
    throw new Error('Version mismatch, context changed underneath this update');
  }
  context.balance += delta;
  context.version += 1;
}

const seenVersion = context.version; // both calls start at version 1

applyUpdate(seenVersion, 50); // succeeds, version becomes 2
applyUpdate(seenVersion, 30); // throws, version is now 2, not 1
